/** A background task, defined once and triggered by its id. */
export interface TaskOptions<TPayload> {
  /** The task's id: what a trigger names. */
  id: string;
  /** Runs once per trigger. */
  run: (payload: TPayload) => Promise<unknown>;
  /** How many times a failed run is retried. */
  retries?: number;
}

export interface TaskHandle {
  id: string;
}

export interface Task<TPayload> {
  trigger(payload: TPayload): Promise<TaskHandle>;
  triggerAndWait(payload: TPayload): Promise<unknown>;
}

export declare function task<TPayload = void>(options: TaskOptions<TPayload>): Task<TPayload>;

/** A job whose options carry two string keys: which one names it is not in the types. */
export interface JobOptions {
  name: string;
  queue: string;
  run: () => Promise<unknown>;
}

export interface Job {
  enqueue(): Promise<void>;
}

export declare function job(options: JobOptions): Job;

export declare const tasks: {
  trigger(id: string, payload: unknown): Promise<TaskHandle>;
};
